import {WEATHER_SCENARIOS,WEATHER_SEASONS,SKINS,weatherExperience,weatherValidate,weatherInitial} from './weather-en.mjs';
import {demoArt,demoScene} from './demo-art.mjs';
import {DEMO_NOTE,DEMO_FIELDS,demoInitial,demoRestore,demoCommand} from './demo-core.mjs';
const $=q=>document.querySelector(q),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='harupoom-english-recording-v1';let data=demoInitial(),view='today',storageFailed=false,toastTimer,dialogFocus=null;
try{data=demoRestore(JSON.parse(localStorage.getItem(KEY)||'null'));}catch{storageFailed=true;}
const navs=[['today','Today','sun'],['source','Source','source'],['prepare','Prepare','bag'],['family','Family','heart'],['moments','Moments','memory']];
const uiIcon=(kind)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${({sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>',source:'<rect x="5" y="3" width="14" height="18" rx="3"/><path d="M9 8h6m-6 4h6m-6 4h3"/>',bag:'<rect x="5" y="6" width="14" height="15" rx="4"/><path d="M9 6V4a3 3 0 0 1 6 0v2M8 13h8m-8 3h8"/>',heart:'<path d="M12 20C-4 10 7-2 12 7c5-9 16 3 0 13Z"/>',memory:'<rect x="3" y="4" width="18" height="16" rx="3"/><circle cx="8" cy="9" r="1.5"/><path d="m3 17 6-5 4 4 3-3 5 5"/>',palette:'<path d="M20 11A8 8 0 1 0 11 20c4 0 1-4 4-5 2 0 5 0 5-4Z"/><circle cx="8" cy="8" r=".6"/><circle cx="13" cy="6" r=".6"/><circle cx="6" cy="13" r=".6"/>'})[kind]||''}</svg>`;
const button=(label,action,attrs='',style='button')=>`<button class="${style}" data-action="${action}" ${attrs}>${label}</button>`;
function notify(text){if($('#demo-dialog').open){const error=$('#demo-dialog-error');if(error){error.textContent=text;error.hidden=false;}}$('#demo-toast').textContent=text;$('#demo-toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#demo-toast').classList.remove('visible'),4200);}
function commit(action){data=demoCommand(data,action);try{localStorage.setItem(KEY,JSON.stringify(data));storageFailed=false;}catch{storageFailed=true;}render();if(storageFailed)notify('Kept on this screen only. Browser storage is unavailable.');}
function closeDialog(){const d=$('#demo-dialog');d.close();dialogFocus?.focus?.({preventScroll:true});}
function dialog(title,body,footer=''){dialogFocus=document.activeElement;const d=$('#demo-dialog');d.innerHTML=`<div class="dialog-heading"><h2 id="dialog-title">${title}</h2><button class="icon-button" data-action="close" aria-label="Close dialog">×</button></div>${body}<p id="demo-dialog-error" class="dialog-error" role="alert" hidden></p><div class="dialog-actions">${button('Cancel','close','','button quiet')}${footer}</div>`;if(!d.open)d.showModal();}
function header(){return `<header class="demo-header"><a class="wordmark" href="#today" aria-label="HaruPoom home"><span class="brand-heart">${uiIcon('heart')}</span><span>HaruPoom<small>LITTLE MOMENTS, HELD TOGETHER</small></span></a><button class="icon-button" data-action="skin-open" aria-label="Choose background skin">${uiIcon('palette')}</button></header>`;}
function sourceBadge(){return `<span class="source-badge">${data.weather.source==='sample'?'Sample weather':'Manually set weather'} · Not a live forecast</span>`;}
function weatherHero(){const w=weatherExperience(data.weather);return `<section class="weather-hero"><div class="weather-copy">${sourceBadge()}<div class="weather-reading"><span>${WEATHER_SCENARIOS.find(x=>x.id===data.weather.condition).label}</span><span>${data.weather.temperature}°</span><span>${WEATHER_SEASONS.find(x=>x.id===data.weather.season).label}</span></div><h1>${esc(w.headline)}</h1><p class="weather-lead">A lighter morning.<br>A little more time together.</p>${button('Change the weather ↗','weather-open','','weather-edit')}</div><div class="weather-art">${demoScene(data.weather)}</div></section>`;}
function preparations(){const w=weatherExperience(data.weather);return `<div class="section-title"><div><span class="eyebrow">01 / PACK A LITTLE CARE</span><h2>By the door, ready to go.</h2></div><span class="tiny">Tap to check</span></div><div class="weather-preps">${w.preparations.map(p=>`<button class="weather-prep ${data.weatherPacked.includes(p.id)?'checked':''}" data-action="weather-pack" data-id="${esc(p.id)}" aria-pressed="${data.weatherPacked.includes(p.id)}"><span class="warm-checkmark" aria-hidden="true">${data.weatherPacked.includes(p.id)?'✓':'+'}</span>${demoArt(p.art)}<b>${esc(p.name)}</b><span>${esc(p.helper)}</span><small>${data.weatherPacked.includes(p.id)?'Checked by you':'Not checked yet'}</small></button>`).join('')}</div>`;}
function today(){const w=weatherExperience(data.weather);return `<div class="page-intro"><span class="eyebrow">THE NEXT MORNING / SAMPLE STORY</span><p>Less to remember. More to notice.</p></div>${weatherHero()}${preparations()}<div class="weather-moments"><article class="weather-talk"><span class="eyebrow">02 / ONE LITTLE QUESTION</span><span class="warm-quote-mark" aria-hidden="true">“</span><h2>${esc(w.question)}</h2><p>No perfect answer needed. Just a moment together.</p></article><article class="weather-experience"><div class="warm-experience-heading"><span class="eyebrow">03 / ${w.indoor?'AN INDOOR MOMENT':'30 SECONDS TOGETHER'}</span><span class="warm-stamp" aria-hidden="true">little<br>moment</span></div><p class="experience-copy">${esc(w.experience)}</p>${button(uiIcon('heart')+' Keep this moment','moment-open','','button soft')}</article></div><p class="warm-safety">${esc(w.safetyNote)}</p><div class="season-note">${demoArt('leaf')}<p>${esc(w.seasonNote)}<br><span>${esc(w.temperatureNote)}</span></p></div><article class="next-card"><div><span class="eyebrow">FROM NOTICE TO NEXT STEP</span><h2>Paper, glue, apron.<br>One less thing to hold in your head.</h2><p>Start with the source. Confirm what matters.</p></div>${button('Check the nursery notice →','navigate','data-view="source"','button primary')}</article><details class="demo-disclosure"><summary>What powers this demo?</summary><p>Fictional notice, sample or manually selected weather, and local rules. No live Meta model, weather feed, nursery app, or family messaging is connected. Your checks and saved cards stay in this browser only. This separate demonstration does not change records in the original workspace.</p></details>`;}
function source(){return `<div class="page-intro"><span class="eyebrow">LAST EVENING / SAMPLE STORY</span><h1>Read less.<br>Keep the source.</h1><p>A clear next step should never lose its evidence.</p></div><div class="source-grid"><section class="panel source-note"><div class="panel-heading"><h2>Nursery notice</h2><span class="source-badge">Fictional sample</span></div><p class="tiny">Manually selected sample · No app access</p><pre>${esc(DEMO_NOTE)}</pre><p class="caption">This demo uses one fixed English example. No notice was fetched from another app.</p></section><section class="panel"><div class="panel-heading"><h2>Check the source</h2><span class="count">${data.reviewed.length} / ${DEMO_FIELDS.length}</span></div><p class="caption">Review each exact quote. These are preset candidates, not a live model analysis.</p>${DEMO_FIELDS.map(f=>`<article class="source-item"><div><b>${esc(f.label)}</b><span class="review-state">${data.reviewed.includes(f.id)?'Source checked':'Needs your review'}</span></div><blockquote>${esc(f.quote)}</blockquote><label class="review-check"><input type="checkbox" data-review="${f.id}" ${data.reviewed.includes(f.id)?'checked':''}> I checked this against the source</label></article>`).join('')}</section></div><div class="flow-note"><b>Read ≠ reviewed ≠ packed.</b><p>A source check never marks a bag as ready.</p></div>${button('Continue to preparation →','navigate','data-view="prepare"','button primary wide')}`;}
function supplyIcon(id){if(id==='paper')return '<svg class="warm-object" viewBox="0 0 100 100" aria-hidden="true"><path d="M20 25h57v58H20Z" fill="#b6c5a5"/><path d="m28 15 59 9-10 59-58-9Z" fill="#edcd8b"/><path d="m43 30 40 19-19 40-40-19Z" fill="#dca98b"/><path d="M31 25h27" stroke="#fff0d0" stroke-width="2"/></svg>';if(id==='glue')return '<svg class="warm-object" viewBox="0 0 100 100" aria-hidden="true"><rect x="31" y="28" width="38" height="58" rx="9" fill="#eee7c9" stroke="#8b9d83" stroke-width="2"/><rect x="28" y="17" width="44" height="19" rx="6" fill="#9cb499"/><rect x="29" y="78" width="42" height="11" rx="4" fill="#9cb499"/><path d="M44 49q6-10 12 0q0 6-6 11q-6-5-6-11" fill="#d5b08c"/></svg>';return demoArt('layer');}
function prepare(){const items=DEMO_FIELDS.filter(f=>f.art);return `<div class="page-intro"><span class="eyebrow">FROM KNOWING TO DOING</span><h1>A place for every<br>little preparation.</h1><p>Bought is not packed. A check means you put it in the bag.</p></div><section class="panel"><div class="panel-heading"><h2>Autumn art morning</h2><span class="source-badge">9:30 a.m. · Sample</span></div><div class="packing-progress"><span>${data.packed.length} of 3 packed</span><div><i style="width:${data.packed.length/3*100}%"></i></div></div><div class="demo-pack-grid">${items.map(f=>`<article class="demo-pack-card ${data.packed.includes(f.id)?'is-packed':''}">${supplyIcon(f.id)}<h3>${f.label}</h3><span class="tiny">${data.reviewed.includes(f.id)?'Source checked':'Review source first'}</span><label class="pack-check"><input type="checkbox" data-pack="${f.id}" ${data.packed.includes(f.id)?'checked':''} ${!data.reviewed.includes(f.id)&&!data.packed.includes(f.id)?'disabled':''}> ${data.packed.includes(f.id)?'Packed by you':'I put it in the bag'}</label>${!data.reviewed.includes(f.id)?button('Review source','navigate','data-view="source"','text-button'):''}</article>`).join('')}</div><div class="bag-summary"><span class="bag-drawing">${uiIcon('bag')}</span><div><b>${data.packed.length===3?'Ready, with your confirmation.':'A little closer to ready.'}</b><p>${data.packed.length?data.packed.map(id=>DEMO_FIELDS.find(f=>f.id===id).label).join(' · '):'Your checked items will appear here.'}</p></div></div></section><p class="caption">Uncheck to undo. Weather preparation stays separate from the nursery notice.</p>${button('See family preview →','navigate','data-view="family"','button primary wide')}`;}
function family(){const left=DEMO_FIELDS.filter(f=>f.art&&!data.packed.includes(f.id));return `<div class="page-intro"><span class="eyebrow">A CLEARER HANDOFF</span><h1>“What’s left?”<br>One calm answer.</h1><p>A shared picture of preparation begins with clear confirmation.</p></div><section class="family-card"><span class="source-badge">Family preview · This device only</span><div class="family-person"><span class="avatar">B</span><div><h2>Caregiver B’s view</h2><p>Preview only. Nothing has been sent.</p></div></div><div class="family-summary"><span>${data.packed.length}<small>PACKED</small></span><span>${3-data.packed.length}<small>STILL TO CHECK</small></span></div><h3>${left.length?'One small next step':'The bag is ready in this demo'}</h3><p>${left.length?'Please check '+left.map(f=>f.label.toLowerCase()).join(', ')+'.':'All three items were explicitly marked as packed by you.'}</p><ul class="family-list">${DEMO_FIELDS.filter(f=>f.art).map(f=>`<li><span>${data.packed.includes(f.id)?'✓':'○'}</span><b>${f.label}</b><small>${data.packed.includes(f.id)?'Packed by you':'Not confirmed'}</small></li>`).join('')}</ul><div class="source-link">${uiIcon('source')} 9:30 a.m. art class · Fictional notice</div></section><div class="flow-note"><b>Clarity without pretending to send.</b><p>Real accounts, invitations and cross-device sharing are not connected in this recording demo.</p></div>${button('Return to a little moment →','navigate','data-view="today"','button primary wide')}`;}
function moments(){return `<div class="page-intro"><span class="eyebrow">MORE THAN A FINISHED CHECKLIST</span><h1>The little things<br>we keep.</h1><p>A question. A shared sound. A moment you chose to save.</p></div>${data.moments.length?`<div class="memories-grid">${data.moments.map(m=>{const w=weatherExperience(m.weather);return `<article class="memory-card">${demoArt(w.indoor?'window':m.weather.condition)}<span class="eyebrow">${new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Seoul',month:'short',day:'numeric'}).format(new Date(m.at))} · ${m.weather.source==='sample'?'SAMPLE WEATHER':'MANUAL WEATHER'}</span><h2>“${esc(m.words)}”</h2><p>${esc(w.experience)}</p><span class="caption">Experience marked by you · Saved on this device</span>${button('Remove card','remove-open',`data-id="${esc(m.id)}"`,'text-button')}</article>`}).join('')}</div>`:`<section class="empty-moments">${demoArt('leaf')}<h2>Small is enough.</h2><p>Keep a weather-inspired moment after you’ve tried it together.</p>${button('Find today’s little moment','navigate','data-view="today"','button soft')}</section>`}<p class="caption">No photos, child names or inferred feelings. This demo stores only your card text, chosen weather and time in this browser.</p>`;}
function skins(){return `<div class="skin-picker">${SKINS.map(s=>`<button class="skin-option skin-${s.id} ${data.skin===s.id?'selected':''}" data-action="skin" data-skin="${s.id}" aria-pressed="${data.skin===s.id}"><span class="skin-dot" aria-hidden="true">${data.skin===s.id?'✓':''}</span><span>${s.label}</span></button>`).join('')}</div>`;}
function render(){document.documentElement.dataset.skin=data.skin;$('#demo-app').innerHTML=`<div class="demo-shell">${header()}<div class="demo-status"><span class="status-dot"></span> INTERACTIVE PROTOTYPE <span>Fictional data · Local only</span></div><main id="main-content">${({today,source,prepare,family,moments}[view]||today)()}${storageFailed?'<p class="storage-warning">Browser storage is unavailable. Changes last only on this screen.</p>':''}</main><footer class="demo-footer"><span>HaruPoom / DayHug</span><button data-action="about">Prototype details</button><button data-action="reset-open">Reset demo</button></footer></div><nav class="demo-nav" aria-label="Main navigation">${navs.map(([id,label,ic])=>`<button data-action="navigate" data-view="${id}" class="${view===id?'active':''}" aria-current="${view===id?'page':'false'}">${uiIcon(ic)}<span>${label}</span></button>`).join('')}</nav>`;}
function navigate(next){if(!navs.some(n=>n[0]===next))return;view=next;if(location.hash!=='#'+next)history.pushState(null,'','#'+next);render();window.scrollTo({top:0,behavior:'instant'});}
function route(){const next=location.hash.slice(1);view=navs.some(n=>n[0]===next)?next:'today';if($('#demo-dialog').open)closeDialog();render();}
document.addEventListener('change',e=>{try{if(e.target.dataset.review){commit({type:'review',id:e.target.dataset.review});$('[data-review="'+e.target.dataset.review+'"]')?.focus?.({preventScroll:true});}if(e.target.dataset.pack){commit({type:'pack',id:e.target.dataset.pack});$('[data-pack="'+e.target.dataset.pack+'"]')?.focus?.({preventScroll:true});}}catch(err){notify(err.message);}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const d=b.dataset;try{switch(d.action){
 case 'navigate':navigate(d.view);break;
 case 'close':closeDialog();break;
 case 'weather-open':dialog('Our morning weather',`<p class="dialog-lead">Explore a scenario. This is not a live forecast.</p><div class="weather-form"><label>Weather<select id="weather-condition">${WEATHER_SCENARIOS.map(s=>`<option value="${s.id}" ${s.id===data.weather.condition?'selected':''}>${s.label}</option>`).join('')}</select></label><label>Temperature (°C)<input type="number" id="weather-temperature" min="-30" max="45" step="0.1" value="${data.weather.temperature}"></label><label>Season<select id="weather-season">${WEATHER_SEASONS.map(s=>`<option value="${s.id}" ${s.id===data.weather.season?'selected':''}>${s.label}</option>`).join('')}</select></label></div><label class="review-check"><input type="checkbox" id="weather-severe" ${data.weather.severe?'checked':''}> Assume severe weather or an alert</label><p class="caption">Severe weather, freezing conditions or 33°C and above switch the experience indoors. Always check official weather information before going out.</p>`,button('Use rainy sample','weather-sample','','button quiet')+button('Apply my scenario','weather-save','','button primary'));break;
 case 'weather-save':{const raw=$('#weather-temperature').value.trim(),value={condition:$('#weather-condition').value,temperature:raw===''?NaN:Number(raw),season:$('#weather-season').value,source:'manual',severe:$('#weather-severe').checked};if(!weatherValidate(value).valid)throw Error('Enter a temperature between -30 and 45°C and choose a weather type and season.');commit({type:'weather',value});closeDialog();notify('Scenario updated. Please check the weather items again.');break;}
 case 'weather-sample':commit({type:'weather',value:weatherInitial()});closeDialog();notify('Rainy autumn sample restored. This is not actual weather.');break;
 case 'weather-pack':commit({type:'weather-pack',id:d.id});$('[data-action="weather-pack"][data-id="'+d.id+'"]')?.focus?.({preventScroll:true});break;
 case 'skin-open':dialog('A color that feels like home',`<p class="dialog-lead">Choose a little atmosphere. Your preparation stays the same.</p>${skins()}<p class="caption">Tap to apply immediately. The color stays selected after you close this panel.</p>`);break;
 case 'skin':commit({type:'skin',value:d.skin});dialog('A color that feels like home',`<p class="dialog-lead">Your choice: ${SKINS.find(s=>s.id===data.skin).label}.</p>${skins()}<p class="caption">Saved in this browser. Your preparation is unchanged.</p>`);break;
 case 'moment-open':dialog('A little moment to keep',`<div class="dialog-art">${demoArt(data.weather.condition)}</div><label class="suggestion-label">Suggested words · Edit before saving<textarea id="moment-words" maxlength="160" rows="3">${esc(weatherExperience(data.weather).question)}</textarea></label><label class="review-check"><input id="moment-confirm" type="checkbox"> We tried this together</label><p class="caption">For this demo, use fictional, non-identifying words only. The card, scenario and save time stay on this device. No message is sent.</p>`,button('Save this little moment','moment-save','','button primary'));break;
 case 'moment-save':if(!$('#moment-confirm').checked)throw Error('Confirm you tried the experience before saving.');commit({type:'moment',words:$('#moment-words').value,confirmed:true});closeDialog();navigate('moments');notify('A little moment, kept here. Identical cards are saved once per day.');break;
 case 'remove-open':dialog('Remove this card?',`<p class="dialog-lead">Only this saved moment will be removed from this browser.</p>`,button('Remove card','remove-confirm',`data-id="${esc(d.id)}"`,'button primary'));break;
 case 'remove-confirm':commit({type:'remove-moment',id:d.id,confirmed:true});closeDialog();break;
 case 'about':dialog('An honest prototype',`<ul class="about-list"><li><b>Works:</b> source checks, packing confirmations, weather scenarios, editable moment cards and four background skins.</li><li><b>Sample:</b> fictional nursery notice and weather-inspired English copy selected by local rules.</li><li><b>Not connected:</b> Meta model, live weather, childcare apps, real family sharing or push alerts.</li><li><b>Storage:</b> this browser only. No external API calls, location requests or personal child data are needed.</li><li><b>Separate workspace:</b> this recording demo does not modify the original Korean workspace.</li></ul>`);break;
 case 'reset-open':dialog('Start a fresh recording?',`<p class="dialog-lead">This clears only this English demo’s checks, skin, weather selection and saved moments. The original workspace is unchanged.</p>`,button('Reset English demo','reset-confirm','','button primary'));break;
 case 'reset-confirm':commit({type:'reset',confirmed:true});closeDialog();navigate('today');notify('Fresh start. Ready for your recording.');break;
 }}catch(err){notify(err.message);}});
window.addEventListener('popstate',route);window.addEventListener('hashchange',route);
window.addEventListener('storage',e=>{if(e.key!==KEY)return;try{data=demoRestore(JSON.parse(e.newValue));if($('#demo-dialog').open)closeDialog();render();notify('Updated from another tab in this browser.');}catch{notify('Could not read a change from another tab.');}});
route();
